def can_form_array(s):
    n = len(s)
    # If there are no 'N's, then the array can be all the same value
    if 'N' not in s:
        return 'YES'
    # If there are 'N's, check if there's a pattern where every pair is different
    for i in range(n):
        if s[i] == 'N' and s[(i + 1) % n] == 'N':
            return 'NO'
    return 'YES'

